public enum ConnectionState: Equatable, Hashable {
    
    /**
     * Not connected, and not trying: no gateway, or the app is in the
     * background
     */
    case offline
    /**
     * Dialing
     */
    case connecting
    /**
     * Reads can arrive
     */
    case connected
    /**
     * The last dial failed; the next starts after `in_secs`
     */
    case retrying(
        /**
         * Seconds to the next dial
         */inSecs: UInt32, 
        /**
         * Why the last one failed
         */error: String
    )





}

