         */width: UInt32, 
        /**
         * Height in points
         */height: UInt32, 
        /**
         * Pixels per point
         */scale: Double
    )
    /**
     * Image `seq` is on screen, so the gateway may send the next
     */
    case drawn(
        /**
         * The image
         */seq: UInt32
    )
    /**
     * A tap on image `seq`
     */
    case tap(
        /**
         * From the left
         */x: Double, 
        /**
         * From the top
         */y: Double, 
        /**
         * The image
         */seq: UInt32
    )
    /**
     * A long press on image `seq`
     */
    case longPress(
        /**
         * From the left
         */x: Double, 
        /**
         * From the top
         */y: Double, 
        /**
         * The image
         */seq: UInt32
    )
    /**
     * Scroll the page under the point by `dx` and `dy`, as fractions of
     * the image; positive scrolls right and down
     */
    case scroll(
        /**
         * From the left
         */x: Double, 
        /**
         * From the top
         */y: Double, 
        /**
         * Horizontal distance
         */dx: Double, 
        /**
         * Vertical distance
         */dy: Double, 
        /**
         * The image
         */seq: UInt32
    )
    /**
     * A key from the key bar
     */
    case key(
        /**
         * Which
         */key: TakeoverKey
    )
    /**
     * Back in the session's history
     */
    case back
    /**
     * Load the page again
     */
    case reload
    /**
     * Open the offer for `reference` with Face ID and fill it
     */
    case fillOffer(
        /**
         * The offer's reference
         */reference: String
    )
    /**
     * The owner finished: ends the takeover and its handoff as done
     */
    case done
    /**
     * The owner gave up: ends the takeover and its handoff as cancelled
     */
    case cancel





}

